 await check('Finger digital ink varies thickness, ignores extra touches, survives undo/redo and reload, and exports',async()=>{await page.locator('.desk-taskbar [data-action=note]').click();await page.locator('.editor-ribbon [data-action=ink]').click();await page.locator('#draw-title').fill('Finger ink test');await page.locator('#ink-mode').selectOption('ink');await page.locator('#ink-size').evaluate(el=>{el.value='15';el.dispatchEvent(new Event('input',{bubbles:true}));});const result=await page.evaluate(()=>{const c=document.querySelector('#draw-canvas'),r=c.getBoundingClientRect();let time=1000;const send=(type,id,x,y,t,kind='touch',pressure=.5,primary=true)=>{const e=new PointerEvent(type,{pointerId:id,pointerType:kind,isPrimary:primary,button:0,buttons:type==='pointerup'?0:1,clientX:r.left+x*r.width,clientY:r.top+y*r.height,pressure,bubbles:true,cancelable:true});Object.defineProperty(e,'timeStamp',{value:t});c.dispatchEvent(e);};for(const [index,dt] of [[0,35],[1,2]]){send('pointerdown',11,.1,.25+index*.25,time);send('pointerdown',12,.9,.9,time+1,'touch',.5,false);for(let i=1;i<=30;i++){time+=dt;send('pointermove',11,.1+i*.02,.25+index*.25,time);send('pointermove',12,.9,.9,time+1,'touch',.5,false);}send('pointerup',12,.9,.9,time+1,'touch',0,false);send('pointermove',11,.72,.25+index*.25,time+=dt);send('pointerup',11,.72,.25+index*.25,time+1);time+=100;}const n=state.items.at(-1),drawing=n.drawing;const pixels=c.getContext('2d').getImageData(650,0,1,c.height).data;const thickness=y=>{let count=0;for(let i=Math.round(y*c.height)-25;i<Math.round(y*c.height)+25;i++)if(pixels[i*4+1]<150)count++;return count;};return {id:n.id,strokes:structuredClone(drawing.strokes),slow:thickness(.25),fast:thickness(.5),before:c.toDataURL()};});assert.equal(result.strokes.length,2);assert(result.strokes.every(s=>s.pressure&&s.points.length===32));assert(result.slow>result.fast+2,JSON.stringify({slow:result.slow,fast:result.fast}));await shot('finger-digital-ink');await page.locator('#draw-undo').click();assert.equal(await page.evaluate(()=>state.items.at(-1).drawing.strokes.length),1);await page.locator('#draw-redo').click();assert.equal(await page.locator('#draw-canvas').evaluate(c=>c.toDataURL()),result.before);await page.evaluate(()=>{window.inkExports=[];let parts=[];window.NotaAndroid.beginExport=(name,mime)=>{parts=[];window.inkExportName=name;return 'ink-test';};window.NotaAndroid.appendExport=(id,data)=>{parts.push(atob(data));return true;};window.NotaAndroid.finishExport=()=>{window.inkExports.push(btoa(parts.join('')));return true;};window.NotaAndroid.cancelExport=()=>{};});await page.locator('#draw-export').click();await page.waitForFunction(()=>window.inkExports.length===1);assert.equal(await page.evaluate(()=>window.inkExportName),'Finger ink test.png');assert.equal(await page.evaluate(()=>window.inkExports[0]),result.before.split(',')[1]);assert.deepEqual(await page.evaluate(id=>NotaCore.validateBackup(JSON.parse(JSON.stringify(state))).items.find(n=>n.id===id).drawing.strokes,result.id),result.strokes);await page.locator('#draw-done').click();await page.waitForFunction(()=>document.querySelector('#save-state').textContent.includes('Saved on device'));await page.reload();await page.waitForSelector(`.card[data-id="${result.id}"]`);await page.locator(`.card[data-id="${result.id}"] .card-body`).click();assert.equal(await page.locator('#draw-canvas').evaluate(c=>c.toDataURL()),result.before);assert.deepEqual(await page.evaluate(id=>state.items.find(n=>n.id===id).drawing.strokes,result.id),result.strokes);await page.locator('#draw-done').click();});
